import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-Multiplication-Operator.md","filePath":"manual-en/Matrix-Multiplication-Operator.md","lastUpdated":1785684581000}'),i={name:"manual-en/Matrix-Multiplication-Operator.md"};function n(d,t,l,p,c,m){return a(),o("div",null,[...t[0]||(t[0]=[r('<h4 id="_16-4-1-6-matrix-multiplication-operator" tabindex="-1">16.4.1.6 Matrix Multiplication Operator ‘*’ <a class="header-anchor" href="#_16-4-1-6-matrix-multiplication-operator" aria-label="Permalink to &quot;16.4.1.6 Matrix Multiplication Operator ‘*’&quot;">​</a></h4><p>If <code>A</code> is an <em>m ×n</em> matrix and <code>B</code> is an <em>n ×p</em> matrix, then <code>A*B</code> is the <em>m ×p</em> matrix multiplication product <code>C</code>. PSPP reports an error if the number of columns in <code>A</code> differs from the number of rows in <code>B</code>.</p><p>The <code>*</code> operator performs elementwise multiplication (see above) if one of its operands is a scalar.</p><p>No built-in operator yields the inverse of matrix multiplication. Instead, multiply by the result of <code>INV</code> or <code>GINV</code>.</p><p>Some examples:</p><table tabindex="0"><thead><tr><th>{1, 2, 3} * {4; 5; 6}</th><th>⇒</th><th>32</th></tr></thead><tbody><tr><td>{4; 5; 6} * {1, 2, 3}</td><td>⇒</td><td>{4, 8, 12; 5, 10, 15; 6, 12, 18}</td></tr></tbody></table>',6)])])}const _=e(i,[["render",n]]);export{u as __pageData,_ as default};
